// Real articles only: every link below comes from a publisher's own RSS feed
// (or a Google News query result). Nothing here is generated by a model.
export type FeedItem = { title: string; url: string; source: string; pubDate: string };

const decode = (s: string) =>
  s.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1")
    .replace(/&amp;/g, "&").replace(/&lt;/g, "<").replace(/&gt;/g, ">")
    .replace(/&quot;/g, '"').replace(/&#0?39;/g, "'").replace(/&apos;/g, "'").trim();

function tag(block: string, name: string) {
  const m = block.match(new RegExp(`<${name}[^>]*>([\\s\\S]*?)</${name}>`));
  return m ? decode(m[1]) : "";
}

async function readFeed(url: string, source: string, limit: number): Promise<FeedItem[]> {
  try {
    const res = await fetch(url, { headers: { "User-Agent": "IndiasporaDigest/1.0 (+https://indiaspora.ch)" }, signal: AbortSignal.timeout(10000) });
    if (!res.ok) return [];
    const xml = await res.text();
    const items = xml.split(/<item[ >]/).slice(1);
    return items.slice(0, limit).map(b => {
      let title = tag(b, "title");
      let src = source;
      // Google News appends " - Publisher"
      const gm = title.match(/^(.*) - ([^-]{2,40})$/);
      if (gm && url.includes("news.google.com")) { title = gm[1]; src = gm[2]; }
      const link = tag(b, "link") || (b.match(/<link>([^<]+)/)?.[1] ?? "");
      return { title, url: link, source: src, pubDate: tag(b, "pubDate") };
    }).filter(i => i.title && /^https?:\/\//.test(i.url));
  } catch {
    return [];
  }
}

const gnews = (q: string, edition = "hl=en-CH&gl=CH&ceid=CH:en") =>
  `https://news.google.com/rss/search?q=${encodeURIComponent(q + " when:7d")}&${edition}`;

export async function fetchDigestNews() {
  const [swiss, europe, bbc, hindu, guardian, toi, local] = await Promise.all([
    readFeed(gnews("Indian community Switzerland OR Swiss-Indian OR \"India Switzerland\""), "News", 8),
    readFeed(gnews("Indian diaspora Europe OR \"Indians in Europe\"", "hl=en-GB&gl=GB&ceid=GB:en"), "News", 8),
    readFeed("https://feeds.bbci.co.uk/news/world/asia/india/rss.xml", "BBC News", 4),
    readFeed("https://www.thehindu.com/news/international/feeder/default.rss", "The Hindu", 4),
    readFeed("https://www.theguardian.com/world/india/rss", "The Guardian", 4),
    readFeed("https://timesofindia.indiatimes.com/rssfeeds/-2128936835.cms", "Times of India", 4),
    readFeed("https://www.thelocal.ch/feeds/rss.php", "The Local Switzerland", 5),
  ]);
  const seen = new Set<string>();
  const dedupe = (a: FeedItem[], n: number) =>
    a.filter(i => { const k = i.title.toLowerCase().slice(0, 60); if (seen.has(k)) return false; seen.add(k); return true; }).slice(0, n);
  return {
    diaspora: dedupe([...swiss, ...europe], 6),
    switzerland: dedupe(local, 3),
    newsrooms: dedupe([...bbc.slice(0, 2), ...guardian.slice(0, 2), ...hindu.slice(0, 2), ...toi.slice(0, 2)], 8),
  };
}
